from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from .api.routes import router
from .api.signals import router as signals_router
from .api.live import router as live_router
from .db import init_db

app=FastAPI(title='Qanas Data Engine',version='0.7.1')
@app.on_event('startup')
def startup(): init_db()
app.include_router(router,prefix='/api'); app.include_router(signals_router,prefix='/api'); app.include_router(live_router,prefix='/api')

HTML=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>قنص</title><style>
:root{--bg:#05090d;--l:#172631;--t:#f3f6f7;--m:#71828e;--g:#42d392;--a:#f2a94b;--gold:#d8b468;--c:#58bce8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:13px Segoe UI,Tahoma,Arial}.wrap{padding:9px 11px}.top,.actions,.filters,.quick{display:flex;align-items:center;gap:7px}.top{height:46px;justify-content:space-between}.brand{display:flex;align-items:center;gap:8px}.logo{width:35px;height:35px;border:1px solid #755f36;border-radius:9px;display:grid;place-items:center;color:var(--gold);font-weight:900;font-size:18px}.brand b{font-size:19px}.btn,.f{border:1px solid var(--l);background:#09131a;color:var(--t);border-radius:8px;padding:7px 9px}.gold{background:#c9a75e;color:#080a0b;font-weight:800}.good,.live{color:var(--g);font-weight:800}.amber{color:var(--a);font-weight:800}.refreshinfo{font-size:10px;color:var(--m)}.refresh.busy{opacity:.35;pointer-events:none}.quick{border:1px solid var(--l);background:#071017;border-radius:9px;padding:6px 8px;overflow:auto;margin-bottom:6px}.qs{white-space:nowrap;padding:0 9px;border-left:1px solid var(--l)}.qs span{font-size:9px;color:var(--m)}.bar{display:flex;gap:6px;align-items:center;position:sticky;top:0;z-index:30;background:#071017;border:1px solid var(--l);border-radius:9px;padding:6px;margin-bottom:6px}.search{flex:1}.search input{width:100%;height:32px;background:#040a0e;border:1px solid #1a2c37;color:white;border-radius:7px;padding:0 9px}.filters{overflow:auto;white-space:nowrap}.f.active{background:#c9a75e;color:#080a0b;font-weight:800}.tablebox{border:1px solid var(--l);border-radius:8px;overflow:auto;max-height:calc(100vh - 108px)}table{width:100%;min-width:1450px;border-collapse:separate;border-spacing:0}th,td{padding:7px 8px;border-bottom:1px solid #12212b;text-align:right;white-space:nowrap;height:42px}th{font-size:9px;color:#748692;background:#081119;position:sticky;top:0}.tc{position:sticky;right:0;background:#071017}.ticker{font-size:14px;font-weight:900}.co{font-size:8px;color:var(--m)}.badge{display:inline-block;padding:4px 7px;border-radius:6px;font-weight:900;background:#292419;color:#e2bd70}.pulse{color:#69e7ae;font-weight:900}.topshow{display:none}.topshow.on{display:block;padding:18px 0 28px}.toph{padding:18px 12px 22px;text-align:center}.toph .crown{font-size:28px}.toph h2{margin:4px 0;font-size:26px;color:#e8c878;letter-spacing:2px}.toph p{margin:0;color:#8d8268;font-size:10px}.topgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px}.topcard{position:relative;overflow:hidden;min-height:160px;padding:20px;border:1px solid #5d4b29;border-radius:18px;background:radial-gradient(circle at 20% 0%,#332817 0,#11100d 35%,#080b0d 75%);box-shadow:inset 0 1px 0 #8d724044,0 12px 30px #0008;cursor:pointer}.topcard:before{content:"";position:absolute;inset:0;background:linear-gradient(125deg,transparent 25%,#d8b46810 50%,transparent 72%);pointer-events:none}.toprank{position:absolute;left:14px;top:12px;color:#bca065;font-size:11px;font-weight:900}.toprank.first{font-size:20px}.topsym{font-size:30px;font-weight:950;letter-spacing:1px}.topco{font-size:9px;color:#766f61;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:75%}.toprise{margin-top:20px;font-size:34px;line-height:1;color:#e5bd62;font-weight:950;text-shadow:0 0 22px #d8b4682b}.toplabel{margin-top:7px;color:#746c5d;font-size:9px}.topcard:nth-child(1){border-color:#b9964c;box-shadow:inset 0 1px 0 #d6b86c66,0 14px 38px #000b,0 0 28px #b88a2817}.topcard:nth-child(1) .topsym{color:#f2d17d}.topcard:nth-child(1) .toprise{font-size:40px}.mobile{display:none}.momctl{grid-column:1/-1;display:flex;align-items:center;gap:9px;padding:10px 12px;margin-bottom:4px;border:1px solid #29414b;border-radius:12px;background:#08151b}.momctl span{font-weight:900}.momctl select{background:#050b0f;color:#f3f6f7;border:1px solid #31505c;border-radius:8px;padding:7px 9px;font-weight:900}.momctl small{color:#71828e}.drawer{display:none;position:fixed;inset:0;background:#000b;z-index:60}.drawer.open{display:block}.sheet{position:absolute;left:0;top:0;height:100%;width:min(540px,96vw);background:#071017;padding:18px;overflow:auto}.close{float:left}.grid,.checks{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:10px}.mini,.check{background:#0a141c;border:1px solid var(--l);border-radius:8px;padding:10px}.check.ok{color:#69dfa8}.timeline{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:14px 0}.step{padding:10px 7px;border:1px solid #1b303a;background:#081219;border-radius:10px}.step span,.mini span{display:block;color:var(--m);font-size:8px}.detailhead{display:flex;justify-content:space-between}.detailprice{font-size:22px;color:var(--g);font-weight:900}.detailneed,.need{margin-top:9px;color:#f2a94b}.fresh{font-size:8px;color:var(--m);margin-top:8px}.lowage{margin-top:8px;color:#77dcae}.lowage.new{color:#ffb65d}
@media(max-width:700px){body{font-size:12px}.wrap{padding:0 8px 82px}.top{min-height:92px;height:auto;margin:0 -8px 10px;padding:14px 12px}.logo{width:44px;height:44px;border-radius:14px;font-size:23px}.brand b{font-size:22px}.actions{max-width:210px;flex-wrap:wrap;justify-content:flex-end}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;border:0;background:transparent;padding:0}.qs{border:1px solid #172a32!important;border-radius:12px;background:#0b161d;padding:9px 4px!important;text-align:center}.qs:nth-child(n+5){display:none}.bar{display:block}.search{margin-bottom:8px}.search input{height:42px}.filters{display:flex;gap:6px}.f{flex:0 0 auto}.tablebox{display:none}.mobile{display:block}.cards{display:grid;gap:11px}.card{background:#0d1921;border:1px solid #1d303a;border-radius:17px;padding:13px}.cardtop{display:flex;justify-content:space-between}.sym{font-size:23px;font-weight:950}.cprice{font-size:20px}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin-top:10px}.metric{display:flex;justify-content:space-between;background:#050b0f;border:1px solid #142630;border-radius:10px;padding:9px}.metric span{color:#71828e;font-size:8px}.sheet{top:auto;bottom:0;height:90vh;width:100%;border-radius:22px 22px 0 0}.timeline{grid-template-columns:repeat(2,1fr)}}
</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="logo">ق</div><b>قنص</b></div><div class="actions"><span id="state" class="good">● متصل</span><span class="refreshinfo">آخر تحديث: <b id="refreshedAt">—</b></span><button id="rb" class="btn refresh" onclick="refreshLive()">تحديث LIVE</button><button id="bb" class="btn gold" onclick="borrow()">تحديث Borrow</button></div></div><div class="quick"><div class="qs"><span>الأسهم</span><b id="total">—</b></div><div class="qs"><span>≤10K</span><b id="scarce">—</b></div><div class="qs"><span>قرب القاع</span><b id="near">—</b></div><div class="qs"><span>🎯 الأجهز</span><b id="ready">—</b></div></div><div class="bar"><div class="search"><input id="q" placeholder="ابحث بالسهم أو الشركة..." oninput="render()"></div><div class="filters"><button class="f active" onclick="sf('all',this)">الكل</button><button class="f" onclick="sf('ready',this)">🎯 الأجهز</button><button class="f" onclick="sf('momentum',this)">⚡ لحظي</button><button class="f" onclick="sf('launched',this)">👑 TOP</button><button class="f" onclick="sf('scarce',this)">Available ≤10,000</button></div></div><div class="tablebox"><table><thead><tr><th class="tc">السهم</th><th>الجاهزية/الزخم</th><th>Available</th><th>CTB</th><th>Rebate</th><th>LIVE</th><th>قاع اليوم</th><th>عن قاع اليوم</th><th>القاع</th><th>عن القاع</th><th>النصف</th><th>الثبات</th></tr></thead><tbody id="rows"></tbody></table></div><div class="mobile"><div id="cards" class="cards"></div></div></div><div id="drawer" class="drawer" onclick="if(event.target===this)closeD()"><div class="sheet"><button class="close" onclick="closeD()">×</button><div id="detail"></div></div></div><script>
let data=[],signals={},live={},filter='all',liveBusy=false,momentumAvail=30000;const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),money=n=>n==null?'—':'$'+Number(n).toFixed(4),pct=n=>n==null?'—':Number(n).toFixed(2)+'%',md=v=>v?String(v).slice(0,10):'—';function rank(x){let s=x.signal;if(s)return s.ready?100:Math.min(99,Number(s.readiness_pct||0));return x.half_level_reached?Math.min(99,Number(x.ready_score||0)):Math.min(74,Number(x.ready_score||0))}function mom(x){let l=x.live||{},p=Number(l.live_price),lo=Number(l.live_day_low);return p>0&&lo>0?(p/lo-1)*100:null}function momTag(x){let m=mom(x);return m==null?'—':m>=15?'🔥 +15%':m>=5?'⚡ +5%':pct(m)}function sf(f,e){filter=f;document.querySelectorAll('.f').forEach(x=>x.classList.remove('active'));e.classList.add('active');render()}function merge(){data=data.map(x=>({...x,signal:signals[x.symbol]||x.signal||null,live:live[x.symbol]||x.live||null}))}async function getj(url){let r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error(r.status);return r.json()}async function base(){try{let d=await getj('/api/hunt');data=d.map(x=>({...x,signal:signals[x.symbol]||null,live:live[x.symbol]||null}));summary();render();state.textContent='● متصل'}catch(e){state.textContent='● خطأ'}}async function refreshLive(){if(liveBusy)return;liveBusy=true;rb.classList.add('busy');rb.textContent='جاري LIVE...';state.textContent='● تحديث LIVE';try{let l=await getj('/api/live-prices');live=Object.fromEntries(l.map(x=>[x.symbol,x]));merge();summary();render();refreshedAt.textContent=new Date().toLocaleTimeString('ar-SA');state.textContent='● متصل'}catch(e){state.textContent='● تعذر LIVE'}finally{liveBusy=false;rb.classList.remove('busy');rb.textContent='تحديث LIVE'}}async function refreshSignals(){try{let s=await getj('/api/signals');signals=Object.fromEntries(s.map(x=>[x.symbol,x]));merge();summary();render()}catch(e){}}function summary(){total.textContent=data.length;scarce.textContent=data.filter(x=>x.available!=null&&x.available<=10000).length;near.textContent=data.filter(x=>(x.signal?.effective_distance_pct??x.distance_from_low_pct)<=10).length;ready.textContent=data.filter(x=>x.signal?.ready||x.signal?.near_ready).length}function filtered(){let a=data,v=q.value.trim().toUpperCase();a=a.filter(x=>!v||x.symbol.includes(v)||(x.company||'').toUpperCase().includes(v));if(filter==='scarce')a=a.filter(x=>x.available!=null&&x.available<=10000);if(filter==='near')a=a.filter(x=>(x.signal?.effective_distance_pct??x.distance_from_low_pct)<=10);if(filter==='ready')a=a.filter(x=>x.signal?.ready||x.signal?.near_ready);if(filter==='momentum')a=a.filter(x=>x.available!=null&&Number(x.available)<=momentumAvail);if(filter==='launched')a=a.filter(x=>x.signal?.launched);a.sort((a,b)=>filter==='momentum'?(Number(a.available)-Number(b.available)||((mom(b)||-999)-(mom(a)||-999))):filter==='ready'?(rank(b)-rank(a)):filter==='launched'?((b.signal?.rise_pct||0)-(a.signal?.rise_pct||0)):(rank(b)-rank(a)));return a}function topCard(x,i){let s=x.signal||{},r=Number(s.rise_pct||0);return `<div class="topcard" onclick="openD('${x.symbol}')"><div class="toprank ${i===0?'first':''}">${i===0?'👑 #1':'#'+(i+1)}</div><div class="topsym">${x.symbol}</div><div class="topco">${x.company||''}</div><div class="toprise">+${r.toFixed(1)}%</div><div class="toplabel">نسبة الانطلاقة · اضغط لعرض التفاصيل</div></div>`}function momentumControls(){return `<div class="momctl"><span>⚡ الحد الأعلى للـ Available</span><select onchange="momentumAvail=Number(this.value);render()"><option value="30000" ${momentumAvail===30000?'selected':''}>≤ 30,000</option><option value="10000" ${momentumAvail===10000?'selected':''}>≤ 10,000</option><option value="5000" ${momentumAvail===5000?'selected':''}>≤ 5,000</option><option value="1000" ${momentumAvail===1000?'selected':''}>≤ 1,000</option><option value="500" ${momentumAvail===500?'selected':''}>≤ 500</option></select><small>نسبة الصعود للعرض فقط ولا تستبعد السهم</small></div>`}function render(){let a=filtered(),isTop=filter==='launched';document.querySelector('.tablebox').style.display=isTop?'none':'';document.querySelector('.mobile').style.display=isTop?'none':'';let ts=document.getElementById('topshow');if(!ts){ts=document.createElement('div');ts.id='topshow';ts.className='topshow';document.querySelector('.tablebox').before(ts)}ts.classList.toggle('on',isTop);if(isTop){ts.innerHTML=`<div class="toph"><div class="crown">👑</div><h2>TOP · نخبة القنص</h2><p>الأسهم التي حققت +40% فأكثر</p></div><div class="topgrid">${a.map(topCard).join('')||'<div>لا توجد نتائج</div>'}</div>`;return}rows.innerHTML=a.map(row).join('');cards.innerHTML=(filter==='momentum'?momentumControls():'')+(a.map(card).join('')||'<div>لا توجد نتائج</div>')}function badge(x){return `<span class="badge">${fmt(rank(x))}%</span>`}function row(x){let s=x.signal||{},l=x.live||{},p=l.live_price??x.current_price,lo=s.effective_low??x.post_split_low,di=s.effective_distance_pct??x.distance_from_low_pct,se=s.effective_sessions??x.stability_sessions;return `<tr onclick="openD('${x.symbol}')"><td class="tc"><b class="ticker">${x.symbol}</b></td><td>${filter==='momentum'?`<span class="pulse">${momTag(x)}</span>`:badge(x)}</td><td>${fmt(x.available)}</td><td>${pct(x.ctb)}</td><td>${pct(x.rebate_rate)}</td><td>${money(p)}</td><td>${money(l.live_day_low)}</td><td class="pulse">${pct(mom(x))}</td><td>${money(lo)}</td><td>${pct(di)}</td><td>${money(x.half_level)}</td><td>${fmt(se)}/4</td></tr>`}function card(x){let s=x.signal||{},l=x.live||{},p=l.live_price??x.current_price,lo=s.effective_low??x.post_split_low,di=s.effective_distance_pct??x.distance_from_low_pct,se=s.effective_sessions??x.stability_sessions;return `<div class="card" onclick="openD('${x.symbol}')"><div class="cardtop"><div><div class="sym">${x.symbol}</div><div class="co">${x.company||''}</div></div><div>${filter==='momentum'?`<div class="pulse">${momTag(x)}</div>`:badge(x)}<div class="cprice live">${money(p)}</div></div></div><div class="metrics"><div class="metric"><span>Available</span><b>${fmt(x.available)}</b></div><div class="metric"><span>Rebate</span><b>${pct(x.rebate_rate)}</b></div>${filter==='momentum'?`<div class="metric"><span>قاع اليوم</span><b>${money(l.live_day_low)}</b></div><div class="metric"><span>صعود من قاع اليوم</span><b class="pulse">${pct(mom(x))}</b></div>`:`<div class="metric"><span>القاع</span><b>${money(lo)}</b></div><div class="metric"><span>عن القاع</span><b>${pct(di)}</b></div><div class="metric"><span>النصف</span><b>${money(x.half_level)}</b></div><div class="metric"><span>الثبات</span><b>${fmt(se)}/4</b></div>`}</div><div class="fresh">LIVE ${l.live_timestamp?'✓':'—'}</div></div>`}function ck(ok,title,val){return `<div class="check${ok?' ok':''}">${ok?'✓':'✕'} ${title}<br><b>${val}</b></div>`}async function openD(symbol){drawer.classList.add('open');detail.innerHTML='جاري التحميل...';try{let s=await getj('/api/stock/'+symbol),g=signals[symbol]||{},l=live[symbol]||{},lo=g.effective_low??s.post_split_low,di=g.effective_distance_pct??s.distance_from_low_pct,se=g.effective_sessions??s.stability_sessions;detail.innerHTML=`<div class="detailhead"><h2>${s.symbol}</h2><div class="detailprice">${money(l.live_price??s.current_price)}</div></div><div class="timeline"><div class="step"><span>قاع اليوم</span><b>${money(l.live_day_low)}</b></div><div class="step"><span>صعود لحظي</span><b>${pct(mom({live:l}))}</b></div><div class="step"><span>Available</span><b>${fmt(s.available)}</b></div><div class="step"><span>Rebate</span><b>${pct(s.rebate_rate)}</b></div><div class="step"><span>القاع</span><b>${money(lo)}</b></div><div class="step"><span>عن القاع</span><b>${pct(di)}</b></div></div><div class="detailneed">${g.missing||'—'}</div>`}catch(e){detail.innerHTML='تعذر التحميل'}}function closeD(){drawer.classList.remove('open')}async function borrow(){bb.disabled=true;try{await fetch('/api/sync/borrow/all')}finally{bb.disabled=false;base()}}async function start(){await base();refreshLive();setTimeout(refreshSignals,500)}start();setInterval(refreshLive,60000);setInterval(refreshSignals,180000);
</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def dashboard(): return HTMLResponse(HTML)